#include <stdio.h>

/* teste do desafio tres-linhas — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A captura do stdout acontece DENTRO do teste (modelo cenario-do-harness):
   freopen manda o stdout para o arquivo temporario, o teste chama a funcao
   do aluno e le o arquivo de volta — stdlib puro, sem runner proprio. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void tela(void);

SM_TEST(tres_linhas_na_ordem) {
    /* captura: o stdout vira o arquivo sm_saida.tmp */
    freopen("sm_saida.tmp", "w", stdout);
    tela();
    fflush(stdout);

    /* leitura linha a linha: cada \n do literal abriu uma linha nova */
    FILE *f = fopen("sm_saida.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a primeira linha", linha, "ola, tela!\n",
              "a primeira coisa impressa e a primeira frase");
    fgets(linha, 80, f);
    checa_str("a segunda linha", linha, "imprimir e facil no C\n",
              "o \n do primeiro printf empurrou esta frase para a segunda linha");
    fgets(linha, 80, f);
    checa_str("a terceira linha", linha, "tres linhas e acabou\n",
              "o \n do segundo printf abriu a terceira linha");
    fclose(f);
}

